class RandomizedSet {
    private java.util.ArrayList<Integer> list;
    private java.util.HashMap<Integer, Integer> map;
    private java.util.Random rand;

    public RandomizedSet() {
        list = new java.util.ArrayList<>();
        map = new java.util.HashMap<>();
        rand = new java.util.Random();
    }

    public boolean insert(int val) {
        if (map.containsKey(val)) return false;
        map.put(val, list.size());
        list.add(val);
        return true;
    }

    public boolean remove(int val) {
        if (!map.containsKey(val)) return false;
        int idx = map.get(val);
        int last = list.get(list.size() - 1);
        list.set(idx, last);
        map.put(last, idx);
        list.remove(list.size() - 1);
        map.remove(val);
        return true;
    }

    public int getRandom() {
        return list.get(rand.nextInt(list.size()));
    }
}

import java.util.*;

class RandomizedSet {
    private int[] vals;
    private int size;
    private Map<Integer, Integer> indexMap;
    private Random rand;

    public RandomizedSet() {
        vals = new int[200001];
        size = 0;
        indexMap = new HashMap();
        rand = new Random();
    }

    public boolean insert(int val) {
        if (indexMap.containsKey(val)) return false;
        vals[size] = val;
        indexMap.put(val, size);
        size++;
        return true;
    }

    public boolean remove(int val) {
        if (!indexMap.containsKey(val)) return false;
        int idx = indexMap.get(val).intValue();
        int lastVal = vals[size - 1];
        vals[idx] = lastVal;
        indexMap.put(lastVal, idx);
        indexMap.remove(val);
        size--;
        return true;
    }

    public int getRandom() {
        return vals[rand.nextInt(size)];
    }
}
